import math

hours = [2, 3, 4, 8, 9, 9]
sat = [62, 58, 66, 88, 92, 85]

def minmax(col):
    lo, hi = min(col), max(col)
    return [(v - lo) / (hi - lo) for v in col]

pts = list(zip(minmax(hours), minmax(sat)))

def dist(p, q):
    return math.sqrt((p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2)

g1 = [0, 1, 2]
g2 = [3, 4, 5]

def inner(g):
    pairs = [dist(pts[i], pts[j]) for i in g for j in g if i < j]
    return sum(pairs) / len(pairs)

def center(g):
    return (sum(pts[i][0] for i in g) / len(g), sum(pts[i][1] for i in g) / len(g))

print("군집1 내 평균 거리 =", round(inner(g1), 3))
print("군집2 내 평균 거리 =", round(inner(g2), 3))
print("군집 간 중심 거리 =", round(dist(center(g1), center(g2)), 3))
